package app.veyra;
import android.content.Context;import app.veyra.model.PlaybackRequest;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class DownloadQueueTest {
 private Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("downloads",0).edit().clear().commit();c.getSharedPreferences("download-queue",0).edit().clear().commit();}
 private String json(String identity,String url)throws Exception{return new JSONObject().put("schemaVersion",1).put("contentId",identity).put("title",identity).put("sources",new JSONArray().put(new JSONObject().put("id","0").put("label","Original").put("url",url).put("mimeType","video/mp4"))).toString();}
 @Test public void catalogJobsPersistEpisodeIdentityWithoutTheirTemporaryUrl()throws Exception{String id=DownloadQueue.add(c,json("current:movie:42:id:7","https://example.invalid/signed.mp4?token=private"),"");JSONObject job=OfflineStore.get(c,id);assertEquals("current",job.getString("provider"));assertEquals("42",job.getString("titleId"));assertEquals("id:7",job.getString("collection"));assertFalse(job.toString().contains("private"));assertFalse(job.has("direct"));}
 @Test public void orderPauseResumeAndRetryReuseStableJobs()throws Exception{String a=DownloadQueue.add(c,json("direct:a","https://example.invalid/a.mp4"),""),b=DownloadQueue.add(c,json("direct:b","https://example.invalid/b.mp4"),"");assertEquals(a,DownloadQueue.next(c));DownloadQueue.move(c,b,-1);assertEquals(b,DownloadQueue.next(c));DownloadQueue.state(c,b,"paused","Paused");assertEquals(a,DownloadQueue.next(c));DownloadQueue.resume(c,b);assertEquals(b,DownloadQueue.next(c));DownloadQueue.state(c,b,"failed","Retry");String retry=DownloadQueue.add(c,json("direct:b","https://example.invalid/b.mp4?fresh=true"),"");assertEquals(b,retry);assertEquals(2,DownloadQueue.ordered(c).size());assertTrue(OfflineStore.get(c,b).getString("direct").contains("fresh=true"));}
 @Test public void recoveryPreservesUserPauseAndCompletedCopies()throws Exception{String a=DownloadQueue.add(c,json("direct:a","https://example.invalid/a.mp4"),""),b=DownloadQueue.add(c,json("direct:b","https://example.invalid/b.mp4"),"");DownloadQueue.state(c,a,"downloading","");DownloadQueue.state(c,b,"complete","");DownloadQueue.recover(c);assertEquals("paused",OfflineStore.get(c,a).getString("state"));assertEquals("complete",OfflineStore.get(c,b).getString("state"));assertNull(DownloadQueue.next(c));}
 @Test public void resolvingDirectJobsRetainsTheirHeadersAndNeverAcceptsRawLoopback()throws Exception{String id=DownloadQueue.add(c,json("direct:a","https://example.invalid/a.mp4"),"");PlaybackRequest resolved=DownloadQueue.resolve(c,OfflineStore.get(c,id));assertEquals("https://example.invalid/a.mp4",resolved.sources.get(0).url);JSONObject bad=new JSONObject().put("direct",json("direct:a","http://127.0.0.1:12345/resource.mp4"));try{DownloadQueue.resolve(c,bad);fail();}catch(Exception expected){}}
 @Test public void differentAudioVersionsRemainDistinctAndKeepTheirLabels()throws Exception{String original=json("current:movie:42:id:7","https://example.invalid/a.mp4");JSONObject dub=new JSONObject(original);dub.getJSONArray("sources").getJSONObject(0).put("id","1").put("label","Dub");String a=DownloadQueue.add(c,original,""),b=DownloadQueue.add(c,dub.toString(),"");assertNotEquals(a,b);assertEquals("Original",OfflineStore.get(c,a).getString("versionLabel"));assertEquals("Dub",OfflineStore.get(c,b).getString("versionLabel"));}
}
